#include <cmath>
#include <algorithm>
#include <stdexcept>
#include "qtrans_runtime.hpp"

namespace futures_options {

// Declarations (so functions can call each other in any order).
double black76(double F, double K, double r, double sigma, double T, bool is_call = true);
double bachelier(double F, double K, double r, double sigma_n, double T, bool is_call = true);
double margrabe(double S1, double S2, double sigma1, double sigma2, double rho, double T, double q1 = 0.0, double q2 = 0.0);

/// Black (1976): option on a forward F, discounted at rate r.
inline double black76(double F, double K, double r, double sigma, double T, bool is_call) {
    double sq = sigma * std::sqrt(T);
    double a = std::log(F / K) / sq + 0.5 * sq;
    double b = a - sq;
    double df = std::exp(-r * T);
    if (is_call) {
        return df * (F * qt::norm_cdf(a) - K * qt::norm_cdf(b));
    }
    return df * (K * qt::norm_cdf(-b) - F * qt::norm_cdf(-a));
}

/// Normal model, as used for rates and spreads that can go negative.
/// sigma_n is an absolute (not percentage) volatility.
inline double bachelier(double F, double K, double r, double sigma_n, double T, bool is_call) {
    double sd = sigma_n * std::sqrt(T);
    if (sd == 0) {
        double intrinsic = is_call ? F - K : K - F;
        return std::exp(-r * T) * std::max(intrinsic, 0.0);
    }
    double m = (F - K) / sd;
    long long w = is_call ? 1LL : -1LL;
    return std::exp(-r * T) * (static_cast<double>(w) * (F - K) * qt::norm_cdf(static_cast<double>(w) * m) + sd * qt::norm_pdf(m));
}

/// Right to exchange asset 2 for asset 1 at T: payoff max(S1 - S2, 0).
inline double margrabe(double S1, double S2, double sigma1, double sigma2, double rho, double T, double q1, double q2) {
    if (!(-1.0 <= rho && rho <= 1.0)) {
        throw std::invalid_argument("correlation must lie in [-1, 1]");
    }
    double sigma = std::sqrt(sigma1 * sigma1 + sigma2 * sigma2 - 2 * rho * sigma1 * sigma2);
    double sq = sigma * std::sqrt(T);
    double a = (std::log(S1 / S2) + (q2 - q1 + 0.5 * (sigma * sigma)) * T) / sq;
    return S1 * std::exp(-q1 * T) * qt::norm_cdf(a) - S2 * std::exp(-q2 * T) * qt::norm_cdf(a - sq);
}

}  // namespace futures_options
